@import "tailwindcss";

:root {
  --background: #060C18;
  --foreground: #DDE2EE;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-site);
  --font-mono: var(--font-geist-mono);
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: #0a0a0a;
    --foreground: #ededed;
  }
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-site, var(--font-sans, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif));
}

/* Base Styles */
.nh {
  background: #060C18;
  color: #DDE2EE;
  font-family: var(--font-site, var(--font-sans, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif));
  min-height: 100vh;
}

/* ─── Card Stack Scroll Effect ─── */
.card-stack-wrapper {
  position: relative;
}

.card-section {
  position: sticky;
  top: 0;
  /* Each card sits above the previous via z-index set inline */
  will-change: transform;
  transform-origin: center top;
  /* Smooth scale-down as next card pushes over it */
  transition: transform 0.1s linear, border-radius 0.1s linear;
  
}

/* When a section is being "stacked" (next card on top),
   the browser scroll handles it naturally via sticky.
   We enhance with a JS-driven scale using CSS var. */
.card-section.scale-on-stack {
  transform: scale(var(--stack-scale, 1)) translateY(var(--stack-y, 0px));
  border-radius: var(--stack-radius, 0px);
}

.sec {
  padding: 40px 28px 32px;
}
.sec-tag {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1.4px;
  color: #1D9E75;
  font-weight: 500;
  margin-bottom: 8px;
}
.sec-h {
  font-size: 20px;
  font-weight: 500;
  color: #fff;
  margin-bottom: 6px;
}
.sec-p {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.4);
  max-width: 480px;
  line-height: 1.7;
  margin-bottom: 24px;
}
.divider {
  border: none;
  border-top: 0.5px solid rgba(255, 255, 255, 0.06);
}

/* Process Flow / Methodology */
.fw-steps {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0;
  margin-top: 40px;
}
.fw-step {
  padding: 16px 10px 16px 0;
  position: relative;
  opacity: 0.4;
  transform: translateY(20px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}
.fw-step.is-active {
  opacity: 1;
  transform: translateY(0);
}
.fw-line-bg {
  position: absolute;
  top: 22px;
  left: 28px;
  right: 0;
  height: 2px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 2px;
}
.fw-line-fill {
  position: absolute;
  top: 22px;
  left: 28px;
  width: 0%;
  height: 2px;
  background: linear-gradient(90deg, #1D9E75, #2ecc71);
  box-shadow: 0 0 12px rgba(29, 158, 117, 0.6);
  border-radius: 2px;
  z-index: 2;
}
.fw-step:last-child .fw-line-bg,
.fw-step:last-child .fw-line-fill {
  display: none;
}
.fw-num {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(6, 12, 24, 1);
  border: 1.5px solid rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.4);
  font-size: 11px;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  position: relative;
  z-index: 3;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.fw-step.is-active .fw-num {
  border-color: #1D9E75;
  background: rgba(29, 158, 117, 0.15);
  color: #1D9E75;
  box-shadow: 0 0 15px rgba(29, 158, 117, 0.4);
  transform: scale(1.15);
}
.fw-step h4 {
  font-size: 14px;
  font-weight: 500;
  color: #fff;
  margin-bottom: 6px;
  transition: color 0.3s;
}
.fw-step.is-active h4 {
  color: #1D9E75;
}
.fw-step p {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.4);
  line-height: 1.6;
}
.fw-step:hover .fw-num {
  background: #1D9E75;
  color: #fff;
  box-shadow: 0 0 20px rgba(29, 158, 117, 0.6);
  transform: scale(1.2);
}
.fw-step:hover h4 {
  color: #fff;
}

/* Target Audience */
.ind-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}
.ind-pill {
  background: rgba(255, 255, 255, 0.03);
  border: 0.5px solid rgba(255, 255, 255, 0.07);
  border-radius: 8px;
  padding: 13px 11px;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: background 0.3s;
}
.ind-pill:hover {
  background: rgba(29, 158, 117, 0.05);
}
.ind-pill i {
  font-size: 14px;
  color: #1D9E75;
  flex-shrink: 0;
}
.ind-pill p {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.6);
  margin: 0;
}

/* Case Studies */
.cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}
.case-card {
  background: rgba(255, 255, 255, 0.03);
  border: 0.5px solid rgba(255, 255, 255, 0.07);
  border-radius: 10px;
  padding: 18px 15px;
  transition: border-color 0.3s;
}
.case-card:hover {
  border-color: rgba(29, 158, 117, 0.3);
}
.case-tag {
  font-size: 10px;
  background: rgba(55, 138, 221, 0.1);
  color: #378ADD;
  border: 0.5px solid rgba(55, 138, 221, 0.2);
  padding: 3px 8px;
  border-radius: 20px;
  display: inline-block;
  margin-bottom: 10px;
}
.case-card h4 {
  font-size: 12px;
  font-weight: 500;
  color: #fff;
  margin-bottom: 5px;
}
.case-card p {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.38);
  line-height: 1.6;
  margin-bottom: 10px;
}
.case-out {
  font-size: 13px;
  font-weight: 500;
  color: #1D9E75;
}

/* Integrations */
.tech-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  justify-content: center;
}
.tech-pill {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.42);
  background: rgba(255, 255, 255, 0.04);
  border: 0.5px solid rgba(255, 255, 255, 0.07);
  padding: 5px 11px;
  border-radius: 20px;
  transition: border-color 0.3s, color 0.3s;
}
.tech-pill:hover {
  border-color: rgba(29, 158, 117, 0.5);
  color: #fff;
}

/* CTA Box */
.cta-box {
  margin: 0 28px 36px;
  background: rgba(29, 158, 117, 0.07);
  border: 0.5px solid rgba(29, 158, 117, 0.2);
  border-radius: 12px;
  padding: 32px 28px;
  text-align: center;
}
.cta-box h2 {
  font-size: 20px;
  font-weight: 500;
  color: #fff;
  margin-bottom: 8px;
}
.cta-box p {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.4);
  margin-bottom: 22px;
  max-width: 400px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.7;
}
.cta-btns {
  display: flex;
  gap: 10px;
  justify-content: center;
}
.btn-p {
  background: #1D9E75;
  color: #fff;
  font-size: 12px;
  font-weight: 500;
  padding: 9px 18px;
  border-radius: 7px;
  border: none;
  cursor: pointer;
  transition: opacity 0.2s;
}
.btn-p:hover { opacity: 0.9; }
.btn-g {
  background: transparent;
  color: rgba(255, 255, 255, 0.6);
  font-size: 12px;
  padding: 9px 16px;
  border-radius: 7px;
  border: 0.5px solid rgba(255, 255, 255, 0.18);
  cursor: pointer;
  transition: background 0.2s;
}
.btn-g:hover { background: rgba(255, 255, 255, 0.05); }

/* Footer */
.footer {
  border-top: 0.5px solid rgba(255, 255, 255, 0.06);
  padding: 24px 28px 18px;
}
.footer-top {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 20px;
}
.footer-brand .logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 15px;
  font-weight: 500;
  color: #fff;
}
.logo-hex {
  width: 26px;
  height: 26px;
  background: #1D9E75;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.footer-brand p {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.28);
  margin-top: 8px;
  line-height: 1.7;
  max-width: 170px;
}
.footer-col h5 {
  font-size: 10px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.45);
  margin-bottom: 9px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}
.footer-col a {
  display: block;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.28);
  margin-bottom: 6px;
  cursor: pointer;
  transition: color 0.2s;
}
.footer-col a:hover { color: #1D9E75; }
.footer-bottom {
  border-top: 0.5px solid rgba(255, 255, 255, 0.06);
  padding-top: 14px;
  display: flex;
  justify-content: space-between;
}
.footer-bottom p {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.2);
}
