}

.ta-grid-bg {
  background-image:
    linear-gradient(to right, var(--ta-line) 1px, transparent 1px),
    linear-gradient(to bottom, var(--ta-line) 1px, transparent 1px);
  background-size: 64px 64px;
}
.ta-noise { background-image: radial-gradient(rgba(255,255,255,0.03) 1px, transparent 1px); background-size: 3px 3px; }

@keyframes ta-pulse  { 0%,100% { transform: scale(1); opacity:.6 } 50% { transform: scale(2.4); opacity:0 } }
@keyframes ta-sweep  { from { transform: rotate(0) } to { transform: rotate(360deg) } }
@keyframes ta-marquee{ from { transform: translateX(0) } to { transform: translateX(-50%) } }

