  color: #fff;
  font-size: 12px;
  font-weight: 500;
  padding: 9px 18px;
  border-radius: 7px;
  border: none;
  box-shadow: 0 10px 24px rgba(29, 158, 117, 0.18);
}

.btn-g {
  background: transparent;
  color: rgba(255, 255, 255, 0.6);
  font-size: 12px;
