  border-radius: 7px;
  border: 0.5px solid rgba(255, 255, 255, 0.18);
}

.hero-btn-primary,
.hero-btn-secondary {
  position: relative;
  
  animation: heroButtonRise 0.9s ease both;
  transform-origin: center bottom;
  transition: transform 220ms ease, box-shadow 220ms ease, border-color 220ms ease, background-position 260ms ease;
}

.hero-btn-primary::before,
.hero-btn-primary::after,
.hero-btn-secondary::before,
.hero-btn-secondary::after {
  display: none;
}

.hero-btn-secondary {
  animation-delay: 0.12s;
}

.hero-btn-primary {
  background: linear-gradient(to top, #117a5a 0 50%, var(--brand) 50% 100%);
  background-size: 100% 200%;
  background-position: top;
}

.hero-btn-secondary {
  background: linear-gradient(to top, rgba(255, 255, 255, 0.09) 0 50%, transparent 50% 100%);
  background-size: 100% 200%;
  background-position: top;
}

.hero-btn-primary:hover,
.hero-btn-primary:focus-visible {
  background-position: bottom;
  transform: translateY(-7px) rotateX(8deg);
  box-shadow: 0 18px 28px rgba(29, 158, 117, 0.26);
}

.hero-btn-secondary:hover,
.hero-btn-secondary:focus-visible {
  background-position: bottom;
  transform: translateY(-7px) rotateX(8deg);
  border-color: rgba(255, 255, 255, 0.34);
  box-shadow: 0 18px 30px rgba(0, 0, 0, 0.24);
}

@keyframes heroButtonRise {
  from {
    opacity: 0;
    filter: blur(6px);
  }

  to {
    opacity: 1;
    filter: blur(0);
  }
}

.hero-right {
  width: clamp(360px, 36vw, 480px);
  flex: 0 0 clamp(360px, 36vw, 480px);
  flex-shrink: 0;
  height: 350px;
  position: relative;
}

.hive-canvas {
