    opacity: 0;
    transform: translateY(24px) rotateX(18deg);
    filter: blur(6px);
  }

  to {
    opacity: 1;
    transform: translateY(0) rotateX(0);
    filter: blur(0);
  }
}

@keyframes outcomesClipSweep {
  from {
    opacity: 0;
    transform: translateX(-18px);
    clip-path: inset(0 100% 0 0 round 9px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
    clip-path: inset(0 0 0 0 round 9px);
  }
}

@keyframes outcomesGreenFlow {
  0%,
  100% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 50%;
  }
}

@keyframes outcomesScaleReveal {
  from {
    opacity: 0;
    transform: scale(0.65);
    filter: blur(5px);
  }

  to {
    opacity: 1;
    transform: scale(1);
    filter: blur(0);
  }
}

@keyframes outcomesFadeSlide {
  from {
    opacity: 0;
    transform: translateX(18px);
    filter: blur(7px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
    filter: blur(0);
  }
}

@keyframes outcomesLineSweep {
  to {
    transform: scaleX(1);
  }
}

@keyframes outcomesDotPulse {
  0%,
  100% {
    box-shadow: 0 0 0 5px rgba(29, 158, 117, 0.1);
  }

  50% {
    box-shadow: 0 0 0 9px rgba(29, 158, 117, 0.03);
  }
}

@keyframes outcomesDescriptionScan {
  0%,
  55%,
  100% {
    transform: translateX(-100%);
  }

  78% {
    transform: translateX(100%);
  }
}

@keyframes outcomesRadarSpin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes outcomeCardReveal {
  from {
    opacity: 0;
    transform: translateY(18px);
    filter: blur(7px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes outcomeCardPop {
  from {
    opacity: 0;
    transform: translateY(24px) scale(0.94);
    filter: blur(10px);
  }

  70% {
    opacity: 1;
    transform: translateY(-4px) scale(1.015);
    filter: blur(0);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

@keyframes outcomeBorderFlow {
  0%,
  100% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 50%;
  }
}

@keyframes outcomeCornerPulse {
  0%,
  100% {
    opacity: 0.42;
    transform: scale(0.9);
  }

  50% {
    opacity: 0.9;
    transform: scale(1.12);
  }
}

@keyframes outcomesOrbitSpin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes outcomeCardSignal {
  0%,
  45%,
  100% {
    transform: translateX(-100%);
  }

  70% {
    transform: translateX(100%);
  }
}

@keyframes systemsDescriptionReveal {
  from {
    opacity: 0;
    transform: translateX(-14px);
    filter: blur(6px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
    filter: blur(0);
  }
}

@keyframes systemsDescriptionLine {
  from {
    transform: scaleY(0);
    transform-origin: top;
  }

  to {
    transform: scaleY(1);
    transform-origin: top;
  }
}

@keyframes systemsDescriptionGlow {
  0% {
    opacity: 0;
    transform: translateX(-10px);
  }

  45% {
    opacity: 1;
  }

  100% {
    opacity: 0;
    transform: translateX(12px);
  }
}

.card h4,
.case-card h4,
.fw-step h4,
.footer-col h5 {
  font-weight: 500;
}

.card h4,
.case-card h4,
.fw-step h4,
.infra-block p {
  font-size: 13px;
  color: #fff;
  margin-bottom: 4px;
}

.card p,
.case-card p,
.cmp-row p {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.38);
  line-height: 1.6;
}

.kpi {
  font-size: 10px;
  color: var(--brand);
  background: rgba(29, 158, 117, 0.1);
  border: 0.5px solid rgba(29, 158, 117, 0.2);
  padding: 2px 8px;
  border-radius: 20px;
  display: inline-block;
  margin-top: 7px;
}

.num-card {
  padding: 18px 14px;
  background: var(--panel-soft);
}

.num-big {
  font-size: 26px;
  font-weight: 500;
  color: #fff;
  line-height: 1;
}

.num-lbl {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.38);
  margin-top: 5px;
  line-height: 1.5;
}

.cmp-col {
  position: relative;
  border-radius: 10px;
  padding: 20px 18px;
  
  backdrop-filter: blur(14px);
  transition: transform 260ms ease, box-shadow 260ms ease, border-color 260ms ease, background 260ms ease;
}

.cmp-col::before {
  content: "";
  position: absolute;
  top: 0;
  left: -120%;
  width: 80%;
  height: 2px;
  pointer-events: none;
  z-index: 0;
}

.cmp-col::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  z-index: 0;
  transform: translateX(-18px);
}

.cmp-col > * {
  position: relative;
  z-index: 1;
}

.comparison-sec {
  position: relative;
  
  animation-timeline: view();
  animation-range: entry 0% cover 42%;
}

.comparison-sec::before {
  content: "";
  position: absolute;
  inset: 22px -20% auto;
  height: 180px;
  background: linear-gradient(100deg, transparent 0%, rgba(29, 158, 117, 0.14) 45%, transparent 70%);
  filter: blur(22px);
  opacity: 0;
  pointer-events: none;
}

.comparison-sec.is-visible::before {
  opacity: 0.8;
  animation: comparisonBeam 9s ease-in-out infinite;
}

.comparison-sec > * {
  position: relative;
  z-index: 1;
}

.comparison-copy {
  display: block;
  width: 100%;
  max-width: 560px;
  margin: 0 0 24px 0 !important;
  padding: 0 !important;
  text-align: left !important;
  transform: none !important;
  animation: none !important;
  opacity: 1 !important;
  filter: none !important;
}

.comparison-copy .sec-tag,
.comparison-copy .sec-h,
.comparison-copy .sec-p {
  display: block;
  text-align: left !important;
  margin-left: 0 !important;
  margin-right: auto !important;
  transform: none !important;
  animation: none !important;
  opacity: 1 !important;
  filter: none !important;
}

.cmp-grid {
  position: relative;
  padding-left: 0;
  align-items: start;
  gap: 18px;
}

.cmp-grid::before {
  display: none;
}

.cmp-grid::after {
  display: none;
}

.comparison-sec.is-visible .cmp-grid::before {
  animation: comparisonRailReveal 1.1s ease 0.18s both;
}

.comparison-sec.is-visible .cmp-grid::after {
  animation: comparisonRailDot 3.2s cubic-bezier(0.65, 0, 0.35, 1) 0.55s infinite;
}

.comparison-rail {
  position: absolute;
  left: 8px;
  top: 96px;
  bottom: 34px;
  width: 3px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(122, 232, 196, 0), rgba(122, 232, 196, 0.92), rgba(226, 75, 74, 0.48), rgba(122, 232, 196, 0));
  box-shadow: 0 0 26px rgba(122, 232, 196, 0.32);
  z-index: 2;
}

.comparison-rail::after {
  content: "";
  position: absolute;
  left: -6px;
  top: 0;
  width: 15px;
  height: 15px;
  border-radius: 999px;
  background: #7ae8c4;
  box-shadow: 0 0 24px rgba(122, 232, 196, 0.58);
  animation: comparisonRailDot 3.2s cubic-bezier(0.65, 0, 0.35, 1) infinite;
}

.cmp-old {
  background: linear-gradient(135deg, rgba(226, 75, 74, 0.06), rgba(255, 255, 255, 0.025));
  border: 1px solid rgba(226, 75, 74, 0.16);
  transform: translateX(0);
  filter: blur(0);
  clip-path: inset(0 0 0 0 round 10px);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.015);
}

.cmp-old::before {
  background: linear-gradient(90deg, transparent, rgba(226, 75, 74, 0.85), transparent);
  animation: comparisonTopSweep 2.7s ease-in-out infinite;
}

.cmp-old::after {
  background: radial-gradient(circle at 0% 50%, rgba(226, 75, 74, 0.18), transparent 52%);
  animation: comparisonSoftWash 3.8s ease-in-out infinite;
}

.comparison-sec.is-visible .cmp-old {
  animation: comparisonCardFlipIn 0.9s cubic-bezier(0.18, 1, 0.32, 1) both, comparisonOldBreath 4.2s ease-in-out 1.1s infinite;
}

.cmp-new {
  background: linear-gradient(135deg, rgba(29, 158, 117, 0.16), rgba(255, 255, 255, 0.03));
  border: 1px solid rgba(122, 232, 196, 0.26);
  transform: translateX(0);
  filter: blur(0);
  clip-path: inset(0 0 0 0 round 10px);
  margin-top: 24px;
  box-shadow: inset 0 0 0 1px rgba(122, 232, 196, 0.04);
}

.cmp-new::before {
  background: linear-gradient(90deg, transparent, rgba(122, 232, 196, 0.95), transparent);
  animation: comparisonTopSweep 2.7s ease-in-out 0.35s infinite;
}

.cmp-new::after {
  background: radial-gradient(circle at 0% 50%, rgba(29, 158, 117, 0.2), transparent 52%);
  animation: comparisonSoftWash 3.8s ease-in-out 0.45s infinite;
}

.comparison-sec.is-visible .cmp-new {
  animation: comparisonCardFlipInReverse 0.9s cubic-bezier(0.18, 1, 0.32, 1) 0.14s both, comparisonNewBreath 4.2s ease-in-out 1.2s infinite;
}

.cmp-old:hover {
  transform: translateY(-8px);
  border-color: rgba(226, 75, 74, 0.22);
  background: rgba(226, 75, 74, 0.035);
  box-shadow: 0 22px 36px rgba(0, 0, 0, 0.26), 0 0 28px rgba(226, 75, 74, 0.08);
}

.cmp-new:hover {
  transform: translateY(-8px);
  border-color: rgba(29, 158, 117, 0.35);
  background: rgba(29, 158, 117, 0.1);
  box-shadow: 0 22px 36px rgba(0, 0, 0, 0.26), 0 0 32px rgba(29, 158, 117, 0.16);
}

.cmp-col h4 {
  font-size: 11px;
  margin-bottom: 14px;
  color: rgba(255, 255, 255, 0.45);
}

.cmp-new h4 {
  color: var(--brand);
}

.cmp-row {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 7px;
  margin-bottom: 9px;
  opacity: 1;
  transform: translateY(0);
  transition: transform 180ms ease;
}

.cmp-row p {
  background-image: linear-gradient(90deg, currentColor, rgba(122, 232, 196, 0.9), currentColor);
  background-size: 240% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  animation: comparisonTextGlide 4.2s ease-in-out infinite;
}

.comparison-sec.is-visible .cmp-row {
  animation: comparisonRowMaskReveal 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.cmp-row:not(:last-child)::before {
  content: "";
  position: absolute;
  left: 2px;
  top: 14px;
  bottom: -10px;
  width: 1px;
  opacity: 0.55;
  transform: scaleY(0);
  transform-origin: top;
  animation-delay: inherit;
}

.comparison-sec.is-visible .cmp-row:not(:last-child)::before {
  animation: comparisonConnector 0.65s ease both;
}

.cmp-old .cmp-row:not(:last-child)::before {
  background: linear-gradient(180deg, rgba(226, 75, 74, 0.45), transparent);
}

.cmp-new .cmp-row:not(:last-child)::before {
  background: linear-gradient(180deg, rgba(29, 158, 117, 0.7), transparent);
}

.cmp-row:hover {
  transform: translateX(4px);
}

.cmp-row:hover .dot {
  transform: rotate(45deg) scale(1.45);
}

.cmp-new .cmp-row p {
  color: rgba(255, 255, 255, 0.7);
}

.cmp-new .cmp-row p::selection,
.cmp-old .cmp-row p::selection {
  background: rgba(29, 158, 117, 0.25);
}

.dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  margin-top: 5px;
  flex-shrink: 0;
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.dot-r {
  background: rgba(226, 75, 74, 0.6);
  box-shadow: 0 0 0 0 rgba(226, 75, 74, 0.22);
  animation: redPulse 2.4s ease-in-out infinite;
}

.dot-g {
  background: var(--brand);
  box-shadow: 0 0 0 0 rgba(29, 158, 117, 0.25);
  animation: greenPulse 2.2s ease-in-out infinite;
}

.infra-grid,
.ind-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.infra-block,
.ind-pill {
  background: var(--panel-soft);
  border: 0.5px solid var(--border);
  border-radius: 8px;
  padding: 13px 11px;
}

.infra-block i,
.ind-pill i {
  width: 28px;
  height: 28px;
  border-radius: 999px;
  background: rgba(29, 158, 117, 0.15);
  color: var(--brand);
  font-size: 13px;
  font-style: normal;
  margin-bottom: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.infra-block span,
.ind-pill p,
.fw-step p {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.3);
  line-height: 1.6;
}

.fw-steps {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0;
}

.fw-step {
  padding: 16px 10px 16px 0;
  position: relative;
}

.fw-line {
  position: absolute;
  top: 22px;
  left: 28px;
  right: 0;
  height: 0.5px;
  background: rgba(29, 158, 117, 0.2);
}

.fw-num {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(29, 158, 117, 0.12);
  border: 0.5px solid rgba(29, 158, 117, 0.3);
  color: var(--brand);
  font-size: 11px;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 10px;
  position: relative;
  z-index: 1;
}

.ind-pill {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ind-pill i {
  margin-bottom: 0;
  flex-shrink: 0;
}

.ind-pill p {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.6);
}

.case-tag {
  font-size: 10px;
  background: rgba(55, 138, 221, 0.1);
  color: #378add;
  border: 0.5px solid rgba(55, 138, 221, 0.2);
  padding: 3px 8px;
  border-radius: 20px;
  display: inline-block;
  margin-bottom: 10px;
}

.case-out {
  font-size: 13px;
  font-weight: 500;
  color: var(--brand);
}

.tech-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  justify-content: center;
  margin-top: 14px;
}

.tech-pill {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.42);
  background: var(--panel);
  border: 0.5px solid var(--border);
  padding: 5px 11px;
  border-radius: 20px;
}

.cta-box {
  position: relative;
  margin: 0 32px 64px;
  
  background:
    radial-gradient(circle at 18% 22%, rgba(29, 158, 117, 0.2), transparent 34%),
    radial-gradient(circle at 82% 28%, rgba(55, 138, 221, 0.12), transparent 32%),
    rgba(255, 255, 255, 0.025);
  border: 1px solid rgba(29, 158, 117, 0.25);
  border-radius: 20px;
  padding: 72px 60px;
  text-align: center;
}

.cta-box::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle, rgba(29, 158, 117, 0.12) 1px, transparent 1px),
    linear-gradient(120deg, transparent, rgba(29, 158, 117, 0.08), transparent);
  background-size: 26px 26px, 100% 100%;
  opacity: 0.42;
  pointer-events: none;
}

.cta-box::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.06), transparent 34%, rgba(0, 0, 0, 0.16));
  pointer-events: none;
}

.cta-box > * {
  position: relative;
  z-index: 1;
}

.cta-box h2 {
  font-size: clamp(32px, 4.5vw, 58px);
  font-weight: 700;
  color: #fff;
  line-height: 1;
  letter-spacing: -0.04em;
  margin-bottom: 14px;
}

.cta-box p {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.4);
  margin-bottom: 26px;
  max-width: 400px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.7;
}

.footer {
  border-top: 0.5px solid rgba(255, 255, 255, 0.06);
  padding: 24px 26px 18px;
}

.footer-top {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 20px;
}

.footer-brand p,
.footer-col a {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.28);
  line-height: 1.7;
}

.footer-brand p {
  margin-top: 8px;
  max-width: 170px;
}

.footer-col h5 {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.45);
  margin-bottom: 9px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.footer-col a {
  display: block;
  margin-bottom: 6px;
}

.footer-bottom {
  border-top: 0.5px solid rgba(255, 255, 255, 0.06);
  padding-top: 14px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.footer-bottom p {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.2);
}

.divider {
  border: none;
  border-top: 0.5px solid rgba(255, 255, 255, 0.06);
}

.inner-hero {
  padding: 12px 26px 20px;
}

.inner-hero h1 {
  font-size: 36px;
  font-weight: 500;
  color: #fff;
  max-width: 720px;
  line-height: 1.15;
  margin-bottom: 12px;
}

.inner-hero p {
  max-width: 580px;
  font-size: 14px;
  line-height: 1.8;
  color: rgba(255, 255, 255, 0.45);
}

@media (max-width: 980px) {
  body {
    padding: 0 10px;
    zoom: 1;
  }

  .nav,
  .hero-wrap,
  .metrics,
  .footer-top,
  .footer-bottom,
  .g3,
  .systems-bento,
  .g2,
  .cmp-grid,
  .infra-grid,
  .fw-steps,
  .ind-grid,
  .nums-grid,
  .cases-grid {
    grid-template-columns: 1fr;
  }

  .nav {
    position: relative;
    top: auto;
    left: auto;
    right: auto;
    width: auto;
    transform: none;
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
    min-height: auto;
    padding: 14px 18px;
    border-radius: 0;
    background: transparent;
  }

  .nh {
    margin: 12px auto;
  }

  .hero-wrap {
    display: block;
  }

  .hero-left,
  .inner-hero,
  .sec,
  .footer,
  .cta-box {
    padding-left: 18px;
    padding-right: 18px;
  }

  .hero-right {
    width: 100%;
    height: 260px;
  }

  .metrics {
    display: grid;
    margin-left: 18px;
    margin-right: 18px;
  }

  .outcomes-layout {
    grid-template-columns: 1fr;
  }

  .outcomes-orbit {
    display: grid;
    gap: 10px;
    min-height: 0;
    border: none;
    background: transparent;
    overflow: visible;
  }

  .outcomes-orbit::before,
  .outcomes-orbit::after,
  .outcomes-orbit-core {
    display: none;
  }

  .outcome-card,
  .outcome-card:nth-of-type(n) {
    position: relative;
    inset: auto;
    width: 100%;
    transform: none;
  }

  .outcomes-deck {
    display: grid;
    gap: 10px;
    min-height: 0;
    perspective: none;
  }

  .outcomes-deck .outcome-card,
  .outcomes-deck .outcome-card:nth-child(n),
  .outcomes-deck:hover .outcome-card:nth-child(n) {
    position: relative;
    left: auto;
    top: auto;
    width: 100%;
    min-height: 132px;
    transform: none;
  }

  .met {
    border-right: none;
    border-bottom: 0.5px solid rgba(255, 255, 255, 0.06);
  }

  .met:last-child {
    border-bottom: none;
  }

  .cmp-grid {
    padding-left: 0;
  }

  .cmp-grid::before,
  .cmp-grid::after {
    display: none;
  }

  .comparison-rail {
    display: none;
  }

  .cmp-new {
    margin-top: 0;
  }

  .footer-top,
  .footer-bottom {
    display: grid;
  }

  .cta-box {
    margin-left: 18px;
    margin-right: 18px;
    padding-top: 48px;
    padding-bottom: 48px;
  }

  .systems-bento .systems-card,
  .systems-bento .systems-card:nth-child(n) {
    grid-column: auto;
    grid-row: auto;
    min-height: 138px;
  }
}

