#comparison .comparison-rail,
#comparison .cmp-grid::before,
#comparison .cmp-grid::after,
#comparison .cmp-col::before,
#comparison .cmp-col::after,
#comparison .cmp-row::before {
  display: none;
}

#comparison .cmp-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding-left: 0;
}

#comparison .cmp-col {
  position: relative;
  border-radius: 10px;
  padding: 20px 18px;
  overflow: visible;
  backdrop-filter: none;
  animation: none;
  transform: none;
  filter: none;
  clip-path: none;
  transition: none;
}

#comparison .cmp-old {
  background: rgba(255, 255, 255, 0.02);
  border: 0.5px solid rgba(255, 255, 255, 0.07);
  box-shadow: none;
}

#comparison .cmp-new {
