.comparison-stage .cmp-new {
  clip-path: polygon(22px 0, 100% 0, 100% 100%, 0 100%);
  padding-left: 34px;
}

.infrastructure-console {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.01), rgba(29, 158, 117, 0.03)),
    rgba(6, 12, 24, 0.14);
}

.infra-console-head {
  max-width: 620px;
}

.infra-console {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 16px;
  align-items: stretch;
}

.infra-console-rail {
  display: grid;
  align-content: space-between;
  justify-items: center;
  padding: 12px 0;
  border-radius: 999px;
  background: rgba(29, 158, 117, 0.08);
  border: 1px solid rgba(29, 158, 117, 0.18);
}

.infra-console-rail span {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #7ae8c4;
  box-shadow: 0 0 14px rgba(122, 232, 196, 0.55);
}

.infrastructure-console .infra-grid {
  grid-template-columns: repeat(4, 1fr);
}

.infrastructure-console .infra-block {
  position: relative;
  
  animation: infraConsoleIn 0.65s ease var(--infra-delay, 0s) both;
  transition: transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease, background 220ms ease;
}

.infrastructure-console .infra-block::after {
  content: "";
  position: absolute;
  left: 12px;
  right: 12px;
  top: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, #7ae8c4, transparent);
  opacity: 0;
  transition: opacity 220ms ease;
}

.infrastructure-console .infra-block:hover {
  transform: translateY(-5px);
  border-color: rgba(122, 232, 196, 0.28);
  background: rgba(29, 158, 117, 0.05);
  box-shadow: 0 18px 34px rgba(0, 0, 0, 0.24), 0 0 22px rgba(29, 158, 117, 0.1);
}

.infrastructure-console .infra-block:hover::after {
  opacity: 1;
}

@keyframes infraConsoleIn {
  from {
    opacity: 0;
    transform: translateY(18px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 980px) {
  .outcomes-board-section,
  .outcomes-board,
  .infra-console {
    grid-template-columns: 1fr;
  }

  .outcomes-board-copy {
    padding-right: 0;
  }

  .outcomes-board-grid,
  .infrastructure-console .infra-grid {
    grid-template-columns: 1fr;
  }

  .infra-console-rail {
    display: none;
  }

  .comparison-stage .cmp-old,
  .comparison-stage .cmp-new {
    clip-path: none;
    padding-left: 18px;
  }
}

