.doc-sheet {
  --sheet-rotate: 0deg;
  --sheet-y: 0px;
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(630px, 84%);
  min-height: 136px;
  padding: 24px 28px 24px 92px;
  border: 1px solid rgba(151, 255, 220, 0.18);
