  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.38), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  transform: translate(-50%, calc(-50% + var(--sheet-y))) rotate(var(--sheet-rotate)) rotateX(4deg);
  transform-origin: center;
  animation: docSheetReveal 0.72s cubic-bezier(0.2, 0.8, 0.2, 1) var(--infra-delay) both;
  transition: transform 0.35s ease, border-color 0.35s ease, box-shadow 0.35s ease;
}

.doc-sheet::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 42px;
  height: 42px;
  background: linear-gradient(135deg, rgba(170, 255, 228, 0.35), rgba(20, 104, 82, 0.16));
  border-left: 1px solid rgba(151, 255, 220, 0.18);
  border-bottom: 1px solid rgba(151, 255, 220, 0.18);
