  --sheet-y: -190px;
}

.doc-sheet-2 {
  --sheet-rotate: 4deg;
  --sheet-y: -96px;
}

.doc-sheet-3 {
  --sheet-rotate: -3deg;
  --sheet-y: 0px;
}

.doc-sheet-4 {
  --sheet-rotate: 6deg;
  --sheet-y: 96px;
}

.doc-sheet-5 {
