  background:
    radial-gradient(circle at 50% 20%, rgba(149, 255, 222, 0.28), transparent 52%),
    rgba(5, 20, 30, 0.94);
  box-shadow:
    inset 0 0 0 1px rgba(148, 255, 221, 0.46),
    inset 0 0 0 12px rgba(148, 255, 221, 0.045),
    0 0 90px rgba(60, 255, 193, 0.2);
  transform: translate(-50%, -50%);
}

.turbine-core span {
  align-self: end;
  color: #9affdc;
  font-size: 32px;
  font-weight: 900;
  letter-spacing: -0.08em;
}

