  color: rgba(238, 255, 250, 0.78);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.turbine-blade {
  --blade-angle: 0deg;
  position: absolute;
  left: 50%;
  top: 50%;
  display: grid;
  grid-template-columns: 48px 1fr;
  align-items: center;
  gap: 16px;
  width: min(360px, 43%);
  min-height: 126px;
  padding: 20px 24px;
  border: 1px solid rgba(145, 255, 220, 0.18);
  background:
    linear-gradient(135deg, rgba(8, 34, 43, 0.84), rgba(3, 13, 22, 0.78)),
    radial-gradient(circle at 0 50%, rgba(119, 255, 212, 0.18), transparent 36%);
  border-radius: 999px 34px 34px 999px;
  box-shadow: 0 22px 70px rgba(0, 0, 0, 0.34);
  transform:
    translate(-50%, -50%)
    rotate(var(--blade-angle))
    translateX(225px)
    rotate(calc(var(--blade-angle) * -1));
  opacity: 0;
  animation: turbineBladeIn 0.78s cubic-bezier(0.2, 0.8, 0.2, 1) var(--infra-delay) forwards;
  transition: border-color 0.35s ease, box-shadow 0.35s ease, background 0.35s ease;
}

.turbine-blade::before {
  content: "";
  position: absolute;
  inset: 10px;
  border: 1px solid rgba(145, 255, 220, 0.08);
  border-radius: inherit;
  pointer-events: none;
}

.turbine-blade::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(100deg, transparent 0 40%, rgba(153, 255, 224, 0.18) 50%, transparent 60% 100%);
  transform: translateX(-120%);
  transition: transform 0.72s ease;
}

.turbine-blade-1 {
  --blade-angle: -88deg;
}

.turbine-blade-2 {
  --blade-angle: -18deg;
}

.turbine-blade-3 {
  --blade-angle: 54deg;
}

.turbine-blade-4 {
  --blade-angle: 126deg;
}

.turbine-blade-5 {
  --blade-angle: 198deg;
}

.turbine-blade:hover {
