#systems.sec,
.outcomes-board-section,
.comparison-stage,
.infrastructure-console {
  border-top: 1px solid rgba(255, 255, 255, 0.055);
  border-bottom: 1px solid rgba(255, 255, 255, 0.035);
}

#systems.sec {
  padding-top: 64px;
  padding-bottom: 56px;
}

.outcomes-board-section {
  padding-top: 60px;
  padding-bottom: 58px;
}

.comparison-stage {
  padding-top: 62px;
  padding-bottom: 58px;
}

.infrastructure-console {
  padding-top: 62px;
  padding-bottom: 60px;
}

.cta-box {
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.36), 0 0 36px rgba(29, 158, 117, 0.08);
}

@keyframes siteBeamDrift {
  from {
    transform: translate3d(-2%, -1%, 0) scale(1);
  }

  to {
    transform: translate3d(2%, 1%, 0) scale(1.04);
  }
}

@keyframes toriiContentRise {
  from {
    opacity: 0;
    transform: translate3d(0, 42px, 0);
    filter: blur(12px);
  }

  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
    filter: blur(0);
  }
}

@keyframes heroLeftGlow {
  from {
    transform: translate3d(-10px, 8px, 0) scale(0.96);
    opacity: 0.72;
  }

  to {
    transform: translate3d(18px, -10px, 0) scale(1.08);
    opacity: 1;
  }
}

@keyframes hiveFrameFloat {
  0%,
  100% {
    transform: skewY(-8deg);
    opacity: 0.45;
  }

  50% {
    transform: skewY(-8deg);
    opacity: 0.9;
  }
}

@keyframes hiveCanvasReveal {
  from {
    opacity: 0;
    clip-path: inset(100% 0 0 0);
    filter: blur(10px);
  }

  to {
    opacity: 1;
    clip-path: inset(0 0 0 0);
    filter: blur(0);
  }
}

@keyframes hiveGlowPulse {
  0%,
  100% {
    transform: scale(0.92);
    opacity: 0.35;
  }

  50% {
    transform: scale(1.12);
    opacity: 0.85;
  }
}

@keyframes heroSideIn {
  from {
    opacity: 0;
    transform: translateX(42px);
    filter: blur(10px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
    filter: blur(0);
  }
}

@keyframes sideLineScan {
  0%,
  100% {
    transform: translateY(-100%);
    opacity: 0.25;
  }

  50% {
    transform: translateY(100%);
    opacity: 1;
  }
}

@keyframes sideDiamondFloat {
  0%,
  100% {
    transform: translate3d(0, 0, 0) rotate(45deg);
    opacity: 0.28;
  }

  50% {
    transform: translate3d(-10px, -8px, 0) rotate(45deg);
    opacity: 0.58;
  }
}

@media (max-width: 980px) {
  .hero-wrap {
    min-height: 0;
  }

  .hero-left {
    padding-top: 48px;
    padding-bottom: 34px;
  }

  .hero-h1 {
    font-size: clamp(36px, 12vw, 52px);
  }

  .hero-right {
    width: 100%;
    height: auto;
  }

  .hero-side {
    padding: 0 18px 28px;
  }

  .hero-partners {
    grid-template-columns: 1fr;
    margin: 0 18px 18px;
  }

  .partners-copy {
    min-height: 80px;
    border-right: 0;
    border-bottom: 1px solid rgba(122, 232, 196, 0.12);
  }

  .partner-logo {
    min-width: 138px;
    min-height: 82px;
    font-size: 20px;
  }
}

#systems .systems-bento .systems-card,
#systems .systems-bento .systems-card:nth-child(n) {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.008)),
    rgba(4, 12, 22, 0.22);
  border-color: rgba(157, 244, 216, 0.11);
  backdrop-filter: blur(2px);
}

#systems .systems-bento .systems-card:hover,
#systems .systems-bento .systems-card:focus-visible,
#systems .systems-bento .systems-card.is-selected {
  background:
    linear-gradient(135deg, rgba(157, 244, 216, 0.055), rgba(255, 255, 255, 0.012)),
    rgba(4, 12, 22, 0.28);
  border-color: rgba(157, 244, 216, 0.22);
}

/* Torii-style systems cards */
#systems .systems-intro .sec-tag,
#systems .systems-intro .systems-description {
  animation: toriiContentRise 0.86s cubic-bezier(0.16, 1, 0.3, 1) both;
}

#systems .systems-intro .systems-description {
  animation-delay: 0.18s;
}

#systems .systems-bento {
  gap: 0;
  border-top: 1px solid rgba(166, 168, 184, 0.18);
  border-left: 1px solid rgba(166, 168, 184, 0.18);
  background: transparent;
}

#systems .systems-bento .systems-card,
#systems .systems-bento .systems-card:nth-child(n) {
  min-height: 252px;
  padding: 34px;
  border: 0;
  border-right: 1px solid rgba(166, 168, 184, 0.18);
  border-bottom: 1px solid rgba(166, 168, 184, 0.18);
  border-radius: 0;
  background: #060c18;
  backdrop-filter: none;
  box-shadow: none;
  transform: none;
  animation: toriiCardRise 0.88s cubic-bezier(0.16, 1, 0.3, 1) both;
}

#systems .systems-bento .systems-card:nth-child(2),
#systems .systems-bento .systems-card:nth-child(5),
#systems .systems-bento .systems-card:nth-child(2):hover,
#systems .systems-bento .systems-card:nth-child(5):hover,
#systems .systems-bento .systems-card:nth-child(2).is-selected,
#systems .systems-bento .systems-card:nth-child(5).is-selected,
#systems .systems-bento .systems-card:hover,
#systems .systems-bento .systems-card:focus-visible,
#systems .systems-bento .systems-card.is-selected {
  transform: none;
}

#systems .systems-bento .systems-card:hover,
#systems .systems-bento .systems-card:focus-visible,
#systems .systems-bento .systems-card.is-selected {
  background:
    radial-gradient(circle at 84% 24%, rgba(157, 244, 216, 0.08), transparent 34%),
    #07101f;
  box-shadow: inset 0 0 0 1px rgba(157, 244, 216, 0.05);
}

#systems .systems-bento .systems-card::before,
#systems .systems-bento .systems-card:nth-child(n)::before,
#systems .systems-bento .systems-card::after,
#systems .systems-bento .systems-card:nth-child(n)::after {
  display: none;
}

#systems .systems-bento .systems-card .card-outline-svg {
  display: block;
  inset: -1px;
  z-index: 4;
}

#systems .systems-bento .systems-card .card-outline-base {
  display: none;
}

#systems .systems-bento .systems-card .card-outline-trace {
  stroke: #9df4d8;
  stroke-width: 1;
  stroke-dasharray: 64 336;
  stroke-dashoffset: 0;
  opacity: 0;
  filter: drop-shadow(0 0 7px rgba(157, 244, 216, 0.75));
}

#systems .systems-bento .systems-card:hover .card-outline-trace,
#systems .systems-bento .systems-card:focus-visible .card-outline-trace,
#systems .systems-bento .systems-card.is-selected .card-outline-trace {
  opacity: 1;
  animation: cardOutlineTrace 1.25s linear infinite;
}

#systems .systems-bento .systems-card .card-icon {
  margin-bottom: 24px;
  transform: none;
}

#systems .systems-bento .systems-card:hover .card-icon,
#systems .systems-bento .systems-card:focus-visible .card-icon,
#systems .systems-bento .systems-card.is-selected .card-icon {
  transform: none;
  color: #9df4d8;
  background: rgba(29, 158, 117, 0.22);
  box-shadow: inset 0 0 0 1px rgba(157, 244, 216, 0.62), 0 0 22px rgba(29, 158, 117, 0.22);
}

#systems .systems-bento .systems-card:hover .card-icon::before,
#systems .systems-bento .systems-card:focus-visible .card-icon::before,
#systems .systems-bento .systems-card.is-selected .card-icon::before {
  background: rgba(29, 158, 117, 0.3);
}

@keyframes toriiCardRise {
  from {
    opacity: 0;
    transform: translate3d(0, 54px, 0);
    filter: blur(12px);
  }

  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
    filter: blur(0);
  }
}

/* Distinct page 3: Outcomes command board */
.outcomes-board-section {
  grid-template-columns: minmax(260px, 0.7fr) minmax(0, 1.3fr);
  gap: 28px;
  padding-top: 72px;
  padding-bottom: 70px;
  background:
    linear-gradient(120deg, rgba(6, 12, 24, 0.9), rgba(6, 12, 24, 0.32)),
    radial-gradient(circle at 18% 28%, rgba(157, 244, 216, 0.12), transparent 34%);
}

.outcomes-board-section .sec-tag,
.outcomes-board-section .sec-h,
.outcomes-board-section .sec-p {
  text-align: left;
}

.outcomes-board {
  grid-template-columns: minmax(220px, 0.85fr) minmax(0, 1.15fr);
  gap: 0;
  border: 1px solid rgba(157, 244, 216, 0.16);
  background: rgba(2, 8, 17, 0.72);
}

.outcomes-board-main {
  border: 0;
  border-right: 1px solid rgba(157, 244, 216, 0.14);
  border-radius: 0;
  background:
    linear-gradient(180deg, rgba(29, 158, 117, 0.13), transparent),
    rgba(255, 255, 255, 0.025);
}

.outcomes-board-main::after {
  inset: auto 22px 22px auto;
  width: 88px;
  height: 88px;
  border-radius: 0;
  border-color: rgba(157, 244, 216, 0.18);
  transform: rotate(45deg);
}

.outcomes-board-grid {
  gap: 0;
}

.outcomes-board-grid .num-card {
  border: 0;
  border-right: 1px solid rgba(157, 244, 216, 0.1);
  border-bottom: 1px solid rgba(157, 244, 216, 0.1);
  border-radius: 0;
  background: rgba(255, 255, 255, 0.018);
}

/* Distinct page 4: Comparison arena */
.comparison-stage {
  padding-top: 76px;
  padding-bottom: 76px;
  background:
    linear-gradient(90deg, rgba(226, 75, 74, 0.09), transparent 35%, rgba(29, 158, 117, 0.1)),
    rgba(2, 7, 16, 0.76);
}

.comparison-stage .cmp-grid {
  position: relative;
  gap: 0;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(6, 12, 24, 0.72);
}

.comparison-stage .cmp-grid::before {
  content: "VS";
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 5;
  display: grid;
  place-items: center;
  width: 54px;
  height: 54px;
  border: 1px solid rgba(157, 244, 216, 0.35);
  border-radius: 50%;
  background: #060c18;
  color: #9df4d8;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.18em;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 28px rgba(29, 158, 117, 0.16);
}

.comparison-stage .cmp-col {
  min-height: 340px;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.comparison-stage .cmp-old {
  clip-path: none;
  border-right: 1px solid rgba(255, 255, 255, 0.12);
  background: linear-gradient(135deg, rgba(226, 75, 74, 0.07), transparent 58%);
}

.comparison-stage .cmp-new {
  clip-path: none;
  padding-left: 28px;
  background: linear-gradient(225deg, rgba(29, 158, 117, 0.09), transparent 58%);
}

.comparison-stage .cmp-row {
  border-radius: 0;
  border-left: 2px solid transparent;
}

.comparison-stage .cmp-new .cmp-row {
  border-left-color: rgba(157, 244, 216, 0.32);
}

.comparison-stage .cmp-old .cmp-row {
  border-left-color: rgba(226, 75, 74, 0.28);
}

/* Distinct page 5: Infrastructure terminal */
.infrastructure-console {
  padding-top: 76px;
  padding-bottom: 78px;
  background:
    linear-gradient(180deg, rgba(6, 12, 24, 0.88), rgba(6, 12, 24, 0.52)),
    linear-gradient(90deg, rgba(157, 244, 216, 0.08) 1px, transparent 1px),
    linear-gradient(rgba(157, 244, 216, 0.06) 1px, transparent 1px);
  background-size: auto, 46px 46px, 46px 46px;
}

.infra-console {
  grid-template-columns: 1fr;
  gap: 0;
  border: 1px solid rgba(157, 244, 216, 0.16);
  background: rgba(1, 7, 14, 0.78);
}

.infra-console-rail {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  height: 38px;
  padding: 0 14px;
  border: 0;
  border-bottom: 1px solid rgba(157, 244, 216, 0.14);
  border-radius: 0;
  background: rgba(255, 255, 255, 0.035);
}

.infra-console-rail span {
  width: 8px;
  height: 8px;
}

.infrastructure-console .infra-grid {
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
}

.infrastructure-console .infra-block {
  min-height: 128px;
  border: 0;
  border-right: 1px solid rgba(157, 244, 216, 0.1);
  border-bottom: 1px solid rgba(157, 244, 216, 0.1);
  border-radius: 0;
  background: rgba(255, 255, 255, 0.016);
}

@media (max-width: 980px) {
  .outcomes-board-section,
  .outcomes-board {
    grid-template-columns: 1fr;
  }

  .outcomes-board-main {
    border-right: 0;
    border-bottom: 1px solid rgba(157, 244, 216, 0.14);
  }

  .comparison-stage .cmp-grid {
    grid-template-columns: 1fr;
  }

  .comparison-stage .cmp-grid::before {
    left: 50%;
    top: 50%;
  }

  .comparison-stage .cmp-old {
    border-right: 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  }

  .comparison-stage .cmp-new {
    padding-left: 18px;
  }

  .infrastructure-console .infra-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 640px) {
  .outcomes-board-grid,
  .infrastructure-console .infra-grid {
    grid-template-columns: 1fr;
  }

  .comparison-stage .cmp-grid::before {
    display: none;
  }
}

/* Stronger redesign: page 3 radial outcomes */
.outcomes-board-section {
  display: block;
  padding: 84px 34px;
  background:
    radial-gradient(circle at 50% 42%, rgba(157, 244, 216, 0.11), transparent 36%),
    linear-gradient(180deg, rgba(3, 9, 18, 0.94), rgba(3, 9, 18, 0.54));
}

.outcomes-board-copy {
  max-width: 640px;
  margin: 0 auto 34px;
  padding: 0;
  text-align: center;
}

.outcomes-board-section .sec-tag,
.outcomes-board-section .sec-h,
.outcomes-board-section .sec-p {
  text-align: center;
  margin-left: auto;
  margin-right: auto;
}

.outcomes-board {
  position: relative;
  display: grid;
  grid-template-columns: 300px 1fr;
  align-items: center;
  gap: 38px;
  max-width: 980px;
  margin: 0 auto;
  border: 0;
  background: transparent;
}

.outcomes-board::before {
  content: "";
  position: absolute;
  left: 150px;
  top: 50%;
  width: 280px;
  height: 280px;
  border: 1px dashed rgba(157, 244, 216, 0.18);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  animation: outcomesOrbit 16s linear infinite;
}

.outcomes-board-main {
  aspect-ratio: 1;
  display: grid;
  align-content: center;
  justify-items: center;
  min-height: 0;
  padding: 30px;
  border: 1px solid rgba(157, 244, 216, 0.28);
  border-radius: 50%;
  background:
    radial-gradient(circle, rgba(29, 158, 117, 0.2), rgba(6, 12, 24, 0.88) 62%),
    #060c18;
  box-shadow: 0 0 70px rgba(29, 158, 117, 0.13);
}

.outcomes-board-main::after {
  display: none;
}

.outcomes-board-main strong {
  margin: 18px 0 10px;
}

.outcomes-board-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.outcomes-board-grid .num-card {
  min-height: 130px;
  border: 1px solid rgba(157, 244, 216, 0.13);
  border-radius: 999px;
  background:
    linear-gradient(90deg, rgba(157, 244, 216, 0.08), rgba(255, 255, 255, 0.018)),
    #07101f;
  transform: skewX(-8deg);
}

.outcomes-board-grid .num-card > * {
  transform: skewX(8deg);
}

@keyframes outcomesOrbit {
  to {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}

/* Stronger redesign: page 4 vertical timeline */
.comparison-stage {
  padding: 88px 36px;
  background:
    linear-gradient(180deg, rgba(226, 75, 74, 0.05), transparent 42%, rgba(29, 158, 117, 0.08)),
    #030914;
}

.comparison-stage .cmp-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 18px;
  border: 0;
  background: transparent;
}

.comparison-stage .cmp-grid::before {
  left: 26px;
  top: 50%;
  width: 2px;
  height: calc(100% - 34px);
  border: 0;
  border-radius: 0;
  background: linear-gradient(180deg, rgba(226, 75, 74, 0.65), rgba(157, 244, 216, 0.8));
  color: transparent;
  transform: translateY(-50%);
  box-shadow: 0 0 24px rgba(157, 244, 216, 0.18);
}

.comparison-stage .cmp-col {
  min-height: 0;
  margin-left: 54px;
  padding: 26px 28px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(6, 12, 24, 0.86);
}

.comparison-stage .cmp-old,
.comparison-stage .cmp-new {
  border-right: 0;
  border-bottom: 0;
  padding-left: 28px;
}

.comparison-stage .cmp-old {
  transform: translateX(-18px);
}

.comparison-stage .cmp-new {
  transform: translateX(18px);
}

.comparison-stage .cmp-row {
  background: transparent;
  border-left-width: 3px;
}

/* Stronger redesign: page 5 diagonal pipeline */
.infrastructure-console {
  padding: 88px 36px;
  background:
    radial-gradient(circle at 12% 20%, rgba(157, 244, 216, 0.12), transparent 30%),
    linear-gradient(135deg, #030914, #06101c);
  background-size: auto;
}

.infra-console-head {
  max-width: 760px;
  margin-bottom: 28px;
}

.infra-console {
  border: 0;
  background: transparent;
}

.infra-console-rail {
  display: none;
}

.infrastructure-console .infra-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  align-items: stretch;
}

.infrastructure-console .infra-block {
  flex: 1 1 210px;
  min-height: 156px;
  padding: 26px;
  border: 1px solid rgba(157, 244, 216, 0.14);
  border-radius: 0;
  background:
    linear-gradient(145deg, rgba(157, 244, 216, 0.08), rgba(255, 255, 255, 0.018)),
    #06101d;
  clip-path: polygon(0 0, calc(100% - 28px) 0, 100% 50%, calc(100% - 28px) 100%, 0 100%, 24px 50%);
}

.infrastructure-console .infra-block:nth-child(odd) {
  transform: translateY(22px);
}

.infrastructure-console .infra-block:hover {
  transform: translateY(10px);
}

.infrastructure-console .infra-block:nth-child(even):hover {
  transform: translateY(-8px);
}

@media (max-width: 980px) {
  .outcomes-board {
    grid-template-columns: 1fr;
  }

  .outcomes-board::before {
    left: 50%;
    top: 150px;
  }

  .outcomes-board-main {
    width: min(300px, 100%);
    margin: 0 auto;
  }

  .comparison-stage .cmp-old,
  .comparison-stage .cmp-new {
    transform: none;
  }
}

/* Torii-inspired unique 3/4/5 sections */
.torii-story-section {
  display: grid;
  grid-template-columns: minmax(260px, 0.85fr) minmax(0, 1.15fr);
  gap: 46px;
  align-items: center;
  padding: 92px 34px;
  background: #040817;
}

.torii-story-copy {
  max-width: 520px;
}

.torii-story-copy h2 {
  margin: 12px 0 22px;
  color: #ffffff;
  font-size: clamp(36px, 5vw, 68px);
  line-height: 0.95;
  letter-spacing: -0.055em;
}

.torii-story-copy p {
  margin: 0 0 18px;
  color: rgba(255, 255, 255, 0.68);
  font-size: 14px;
  line-height: 1.9;
}

.torii-story-copy strong {
  display: block;
  margin-top: 22px;
  color: #ffffff;
  font-size: 18px;
}

.torii-story-card {
  position: relative;
  
  min-height: 520px;
  border: 1px solid rgba(166, 168, 184, 0.2);
  background:
    radial-gradient(circle at 74% 28%, rgba(157, 244, 216, 0.14), transparent 28%),
    #070b19;
}

.story-marquee {
  display: flex;
  width: max-content;
  padding: 22px 0;
  border-bottom: 1px solid rgba(166, 168, 184, 0.16);
  animation: storyMarquee 18s linear infinite;
}

.story-marquee span {
  padding-right: 34px;
  color: rgba(255, 255, 255, 0.12);
  font-size: clamp(34px, 5vw, 72px);
  font-weight: 900;
  letter-spacing: -0.06em;
  white-space: nowrap;
}

.story-feature {
  padding: 42px;
}

.story-feature strong {
  display: block;
  color: #ffffff;
  font-size: clamp(58px, 8vw, 112px);
  line-height: 0.85;
  letter-spacing: -0.08em;
}

.story-feature span {
  display: block;
  margin-top: 16px;
  color: #9df4d8;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.story-feature p {
  max-width: 360px;
  color: rgba(255, 255, 255, 0.62);
  line-height: 1.75;
}

.story-stats {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  border-top: 1px solid rgba(166, 168, 184, 0.16);
}

.story-stat {
  padding: 22px;
  border-right: 1px solid rgba(166, 168, 184, 0.12);
  border-bottom: 1px solid rgba(166, 168, 184, 0.12);
  animation: toriiContentRise 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.story-stat span {
  color: #ffffff;
  font-size: 24px;
  font-weight: 900;
}

.story-stat p {
  margin: 8px 0 0;
  color: rgba(255, 255, 255, 0.52);
  font-size: 11px;
  line-height: 1.55;
}

.torii-pillars-section {
  padding: 92px 34px;
  background:
    linear-gradient(90deg, #040817, rgba(6, 12, 24, 0.72)),
