/* Totally different 3rd page: outcome radar */
.outcome-radar-section {
  display: grid;
  grid-template-columns: minmax(280px, 0.72fr) minmax(460px, 1.28fr);
  gap: 34px;
  align-items: center;
  padding: 88px 38px;
  
  background:
    radial-gradient(circle at 72% 50%, rgba(157, 244, 216, 0.1), transparent 34%),
    #050914;
}

.outcome-radar-copy {
  position: relative;
  z-index: 2;
}

.outcome-radar-copy .sec-h {
  color: #ffffff;
  font-size: clamp(42px, 5.8vw, 82px);
  line-height: 0.94;
  letter-spacing: -0.07em;
}

.outcome-radar-copy .sec-p {
  max-width: 460px;
  color: rgba(255, 255, 255, 0.68);
  font-size: 15px;
  line-height: 1.85;
}

.outcome-radar {
  position: relative;
  min-height: 620px;
  overflow: visible;
}

.radar-core {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 3;
  display: grid;
  place-items: center;
  width: 260px;
  height: 260px;
  padding: 28px;
  border: 1px solid rgba(157, 244, 216, 0.32);
  clip-path: polygon(50% 0, 93% 25%, 93% 75%, 50% 100%, 7% 75%, 7% 25%);
  text-align: center;
  background:
    radial-gradient(circle, rgba(29, 158, 117, 0.24), rgba(6, 12, 24, 0.96) 64%),
    #060c18;
  box-shadow: 0 0 80px rgba(29, 158, 117, 0.16);
  transform: translate(-50%, -50%);
}

.radar-core > span {
  color: #9df4d8;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.radar-core strong {
  color: #ffffff;
  font-size: 72px;
  line-height: 0.8;
  letter-spacing: -0.08em;
}

.radar-core p {
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 12px;
  line-height: 1.55;
}

.radar-rings {
  position: absolute;
  inset: 0;
}

.radar-rings span {
  position: absolute;
  left: 50%;
  top: 50%;
  border: 1px solid rgba(157, 244, 216, 0.13);
  clip-path: polygon(50% 0, 93% 25%, 93% 75%, 50% 100%, 7% 75%, 7% 25%);
  transform: translate(-50%, -50%);
  animation: radarPulse 4.8s ease-in-out infinite;
}

.radar-rings span:nth-child(1) {
  width: 360px;
  height: 360px;
}

.radar-rings span:nth-child(2) {
  width: 500px;
  height: 500px;
  animation-delay: 0.4s;
}

.radar-rings span:nth-child(3) {
  width: 640px;
  height: 640px;
  animation-delay: 0.8s;
}

.radar-rings::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 320px;
  height: 1px;
  background: linear-gradient(90deg, rgba(157, 244, 216, 0.6), transparent);
  transform-origin: left center;
  animation: radarSweep 4s linear infinite;
}

.radar-node {
  position: absolute;
  z-index: 4;
  width: 168px;
  min-height: 126px;
  display: grid;
  align-content: center;
  padding: 22px 18px;
  border: 1px solid rgba(157, 244, 216, 0.16);
  clip-path: polygon(50% 0, 96% 24%, 96% 76%, 50% 100%, 4% 76%, 4% 24%);
  background: rgba(6, 12, 24, 0.88);
  left: 50%;
  top: 50%;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, -50%) scale(0.25) rotate(18deg);
  transition: opacity 260ms ease, transform 520ms cubic-bezier(0.16, 1, 0.3, 1);
}

.outcome-radar:hover .radar-node,
.outcome-radar:focus-within .radar-node,
.outcome-radar-section:hover .radar-node {
  opacity: 1;
  pointer-events: auto;
}

.radar-node strong {
  display: block;
  color: #ffffff;
  font-size: 24px;
  line-height: 1;
}

.radar-node span {
  display: block;
  margin-top: 8px;
  color: rgba(255, 255, 255, 0.58);
  font-size: 11px;
  line-height: 1.45;
}

.radar-node-1 {
  transition-delay: 0.02s;
}

.radar-node-2 {
  transition-delay: 0.08s;
}

.radar-node-3 {
  transition-delay: 0.14s;
}

.radar-node-4 {
  transition-delay: 0.2s;
}

.radar-node-5 {
  transition-delay: 0.26s;
}

.outcome-radar:hover .radar-node-1,
.outcome-radar:focus-within .radar-node-1,
.outcome-radar-section:hover .radar-node-1 {
  transform: translate(-50%, -50%) translate(0, -260px) scale(1) rotate(0deg);
}

.outcome-radar:hover .radar-node-2,
.outcome-radar:focus-within .radar-node-2,
.outcome-radar-section:hover .radar-node-2 {
  transform: translate(-50%, -50%) translate(250px, -92px) scale(1) rotate(0deg);
}

.outcome-radar:hover .radar-node-3,
.outcome-radar:focus-within .radar-node-3,
.outcome-radar-section:hover .radar-node-3 {
  transform: translate(-50%, -50%) translate(188px, 215px) scale(1) rotate(0deg);
}

.outcome-radar:hover .radar-node-4,
.outcome-radar:focus-within .radar-node-4,
.outcome-radar-section:hover .radar-node-4 {
  transform: translate(-50%, -50%) translate(-188px, 215px) scale(1) rotate(0deg);
}

.outcome-radar:hover .radar-node-5,
.outcome-radar:focus-within .radar-node-5,
.outcome-radar-section:hover .radar-node-5 {
  transform: translate(-50%, -50%) translate(-250px, -92px) scale(1) rotate(0deg);
}

/* Alternate reveal: right-side hex drawer */
.radar-node {
  left: auto;
  right: -22px;
  top: 50%;
  width: 210px;
  min-height: 104px;
  opacity: 0;
  transform: translate3d(72px, -50%, 0) scale(0.96);
  border-left: 3px solid rgba(157, 244, 216, 0.48);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 50%, calc(100% - 22px) 100%, 0 100%, 18px 50%);
}

.radar-node-1,
.radar-node-2,
.radar-node-3,
.radar-node-4,
.radar-node-5 {
  left: auto;
}

