/* Actual different pages: comparison timeline + infrastructure orbit */
.comparison-timeline-section {
  position: relative;
  min-height: 100vh;
  padding: 100px 38px;
  
  background:
    radial-gradient(circle at 12% 18%, rgba(157, 244, 216, 0.16), transparent 28%),
    linear-gradient(180deg, #030812, #040a14);
}

.comparison-timeline-head {
  max-width: 900px;
  margin-bottom: 34px;
}

.comparison-timeline-head .sec-tag,
.comparison-timeline-head .sec-h,
.comparison-timeline-head .sec-p {
  max-width: 820px;
  margin-left: 0;
  margin-right: 0;
  text-align: left;
}

.comparison-timeline-head .sec-h {
  color: #ffffff;
  font-size: clamp(30px, 3.8vw, 52px);
  line-height: 1.04;
  letter-spacing: -0.045em;
}

.comparison-timeline-head .sec-p {
  max-width: 560px;
  font-size: 14px;
  line-height: 1.65;
}

.comparison-timeline {
  position: relative;
  display: grid;
  gap: 9px;
}

.comparison-timeline::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  background: linear-gradient(180deg, transparent, rgba(157, 244, 216, 0.42), transparent);
}

.timeline-pair {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 64px minmax(0, 1fr);
  align-items: stretch;
  min-height: 82px;
  animation: timelinePairIn 0.7s ease var(--pair-delay, 0s) both;
}

.timeline-old,
.timeline-new {
  position: relative;
  display: grid;
  align-content: center;
  padding: 14px 18px;
  background: rgba(255, 255, 255, 0.025);
  box-shadow: inset 0 0 0 1px rgba(166, 168, 184, 0.08);
}

.timeline-old {
  padding-right: 32px;
  text-align: right;
  clip-path: polygon(0 0, 100% 0, calc(100% - 26px) 100%, 0 100%);
}

.timeline-new {
  padding-left: 32px;
  clip-path: polygon(26px 0, 100% 0, 100% 100%, 0 100%);
  background:
    linear-gradient(90deg, rgba(157, 244, 216, 0.09), transparent 48%),
    rgba(157, 244, 216, 0.025);
}

.timeline-old::after,
.timeline-new::before {
  content: "";
  position: absolute;
  top: 50%;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  transform: translateY(-50%);
}

.timeline-old::after {
  right: 14px;
  background: rgba(255, 255, 255, 0.32);
}

.timeline-new::before {
  left: 14px;
  background: #9df4d8;
  box-shadow: 0 0 18px rgba(157, 244, 216, 0.45);
}

.timeline-old p,
.timeline-new p {
  margin: 0;
  color: rgba(255, 255, 255, 0.72);
