  line-height: 1.42;
}

.timeline-node {
  position: relative;
  display: grid;
  place-items: center;
}

.timeline-node span {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  color: #ffffff;
  font-size: 10px;
  font-weight: 900;
  background: rgba(157, 244, 216, 0.08);
  box-shadow: inset 0 0 0 1px rgba(157, 244, 216, 0.28), 0 0 34px rgba(157, 244, 216, 0.16);
  clip-path: polygon(25% 5%, 75% 5%, 100% 50%, 75% 95%, 25% 95%, 0 50%);
}

.timeline-pair:hover .timeline-new {
  background:
    linear-gradient(90deg, rgba(157, 244, 216, 0.16), transparent 54%),
    rgba(157, 244, 216, 0.04);
}

.infrastructure-orbit-section {
  position: relative;
  display: grid;
  grid-template-columns: minmax(280px, 0.62fr) minmax(0, 1.38fr);
  gap: clamp(38px, 5vw, 78px);
