  line-height: 1.65;
}

.infrastructure-orbit {
  position: relative;
  min-height: 720px;
}

.orbit-core {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 3;
  display: grid;
  place-items: center;
  width: 180px;
  height: 180px;
  color: #ffffff;
  font-size: 34px;
  font-weight: 950;
  letter-spacing: -0.08em;
