  transform: translate(-50%, -50%);
}

.infrastructure-orbit::before,
.infrastructure-orbit::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  border: 1px solid rgba(157, 244, 216, 0.12);
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

.infrastructure-orbit::before {
  width: 72%;
  height: 72%;
}

.infrastructure-orbit::after {
  width: 94%;
  height: 94%;
}

.orbit-item {
