  min-height: 150px;
  padding: 20px;
  background:
    radial-gradient(circle at 82% 16%, rgba(157, 244, 216, 0.16), transparent 23%),
    #06101d;
  box-shadow: inset 0 0 0 1px rgba(157, 244, 216, 0.1);
  clip-path: polygon(0 0, calc(100% - 26px) 0, 100% 26px, 100% 100%, 0 100%);
