.orbit-item-4 { right: 12%; bottom: 8%; }
.orbit-item-5 { left: 12%; bottom: 8%; }
.orbit-item-6 { left: 0; top: 42%; }

.orbit-item span {
  color: #9df4d8;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.18em;
}

.orbit-item h3 {
  margin: 18px 0 10px;
  color: #ffffff;
  font-size: clamp(21px, 2.3vw, 34px);
  line-height: 0.98;
  letter-spacing: -0.055em;
}

.orbit-item p {
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
