@keyframes timelinePairIn {
  from {
    opacity: 0;
    transform: translateY(22px);
  }
}

@keyframes orbitItemIn {
  from {
    opacity: 0;
    transform: scale(0.94);
  }
}

@media (max-width: 980px) {
  .comparison-timeline-section,
  .infrastructure-orbit-section {
    grid-template-columns: 1fr;
  }

  .timeline-pair {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .comparison-timeline::before,
  .timeline-node {
    display: none;
