  inset: 0;
  background: radial-gradient(circle at 50% 50%, rgba(26, 233, 171, 0.07) 0%, transparent 60%);
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}

.bento-widget-card.span-2 {
  grid-column: span 2;
}

.bento-widget-card.span-row-2 {
  grid-row: span 2;
  min-height: 520px;
}

.bento-widget-card:hover {
  transform: translateY(-6px);
  border-color: rgba(26, 233, 171, 0.28);
  box-shadow: 
    0 22px 50px rgba(0, 0, 0, 0.55),
    0 0 25px rgba(26, 233, 171, 0.06);
}

.bento-widget-card:hover::before {
  opacity: 1;
}

.bento-widget-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  width: 100%;
}

.bento-widget-num {
