}

.bento-trend-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  color: #1ae9ab;
  padding: 4px 10px;
  background: rgba(26, 233, 171, 0.06);
  border: 1px solid rgba(26, 233, 171, 0.14);
