/* Animations for widgets inside cards */
@keyframes bentoRadar {
  0% { r: 5; opacity: 1; stroke-width: 1.5; }
  100% { r: 50; opacity: 0; stroke-width: 0.5; }
}

.bento-anim-radar {
  animation: bentoRadar 2.2s infinite cubic-bezier(0.215, 0.61, 0.355, 1);
  transform-origin: center;
}

.bento-anim-gear {
  animation: spinGear 8s linear infinite;
  transform-origin: center;
}

.bento-anim-gear-rev {
  animation: spinGearRev 6s linear infinite;
  transform-origin: center;
}

.bento-anim-dash {
  stroke-dasharray: 6 5;
  animation: flowParticles 1.5s linear infinite;
}

