  letter-spacing: 1px;
  padding: 8px 6px;
  border-radius: 20px;
  cursor: pointer;
  z-index: 2;
  transition: all 0.3s;
}

.toggle-btn.active {
  color: #fff;
}

.toggle-bg-slider {
  position: absolute;
  top: 4px;
  bottom: 4px;
  width: calc(50% - 4px);
  border-radius: 20px;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 1;
}

.toggle-bg-slider.left {
  left: 4px;
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.25);
}

.toggle-bg-slider.right {
  left: calc(50%);
  background: rgba(26, 233, 171, 0.12);
  border: 1px solid rgba(26, 233, 171, 0.25);
}

