  stroke-width: 4px;
}

.radial-fill-ring {
  fill: none;
  stroke-width: 4px;
  stroke-linecap: round;
  stroke-dasharray: 125.6;
  stroke-dashoffset: 125.6;
  transition: stroke-dashoffset 1s ease-out;
