  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 20px;
  padding: 28px;
  min-height: 220px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: relative;
  
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.telemetry-card:hover {
  transform: translateY(-4px);
  border-color: rgba(var(--card-glow-color, 26, 233, 171), 0.25);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.5), 0 0 30px rgba(var(--card-glow-color, 26, 233, 171), 0.08);
}

.telemetry-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  width: 100%;
}

.telemetry-status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: rgba(255, 255, 255, 0.45);
}

.telemetry-status-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background-color: rgb(var(--card-glow-color, 26, 233, 171));
  box-shadow: 0 0 8px rgb(var(--card-glow-color, 26, 233, 171));
  animation: telemetry-pulse 2s infinite ease-in-out;
}

@keyframes telemetry-pulse {
  0%, 100% { opacity: 0.4; transform: scale(0.9); }
  50% { opacity: 1; transform: scale(1.1); }
}

.telemetry-visual-container {
  width: 80px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
}

.telemetry-body {
  margin-top: 24px;
}

.telemetry-value-display {
  display: flex;
  align-items: baseline;
  gap: 2px;
}

.telemetry-val {
  font-size: 38px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -1px;
  color: rgb(var(--card-glow-color, 26, 233, 171));
  text-shadow: 0 0 20px rgba(var(--card-glow-color, 26, 233, 171), 0.2);
}

.telemetry-label-text {
  font-size: 13.5px;
  line-height: 1.55;
  color: rgba(255, 255, 255, 0.65);
  margin-top: 10px;
  font-weight: 300;
}

/* Option B Parallel Row Comparison Styles */
.comparison-row-stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
  margin-top: 32px;
}

.comparison-row-panel {
