}

.comparison-row-card.modern {
  border: 1px solid rgba(26, 233, 171, 0.12);
}

.comparison-row-panel:hover .comparison-row-card.legacy {
  border-color: rgba(239, 68, 68, 0.22);
  background: rgba(239, 68, 68, 0.015);
}

.comparison-row-panel:hover .comparison-row-card.modern {
  border-color: rgba(26, 233, 171, 0.3);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.5), 0 0 20px rgba(26, 233, 171, 0.06);
  background: rgba(26, 233, 171, 0.025);
}

.comparison-row-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  font-size: 11px;
  font-weight: 900;
  margin-right: 16px;
  flex-shrink: 0;
}

.comparison-row-icon.legacy {
  color: #ef4444;
  background: rgba(239, 68, 68, 0.06);
  border: 1px solid rgba(239, 68, 68, 0.15);
}

.comparison-row-icon.modern {
  color: #1ae9ab;
  background: rgba(26, 233, 171, 0.06);
  border: 1px solid rgba(26, 233, 171, 0.2);
  box-shadow: 0 0 8px rgba(26, 233, 171, 0.1);
}

.comparison-row-text {
  font-size: 13.5px;
  line-height: 1.55;
  margin: 0;
}

.comparison-row-text.legacy {
  color: rgba(255, 255, 255, 0.45);
}

.comparison-row-text.modern {
  color: #ffffff;
  font-weight: 500;
}

.comparison-row-arrow {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #040a12;
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: rgba(255, 255, 255, 0.3);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.5);
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  flex-shrink: 0;
  z-index: 5;
}

.comparison-row-panel:hover .comparison-row-arrow {
  color: #1ae9ab;
  border-color: rgba(26, 233, 171, 0.35);
  box-shadow: 0 0 12px rgba(26, 233, 171, 0.25);
  transform: scale(1.1);
}

@media (max-width: 768px) {
  .comparison-row-panel {
    flex-direction: column;
    gap: 8px;
    background: rgba(255, 255, 255, 0.01);
    border: 1px solid rgba(255, 255, 255, 0.03);
    border-radius: 20px;
    padding: 16px;
  }
  
  .comparison-row-card {
    width: 100%;
    min-height: auto;
    padding: 12px 16px;
    background: transparent;
    border: none;
    box-shadow: none;
  }
  
  .comparison-row-arrow {
    transform: rotate(90deg);
    width: 30px;
    height: 30px;
    font-size: 12px;
  }
  
  .comparison-row-panel:hover .comparison-row-arrow {
    transform: scale(1.1) rotate(90deg);
  }
}

