/* Page 4 split comparison design */
.comparison-split {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 76px minmax(0, 1fr);
  align-items: stretch;
  gap: 0;
  margin-top: 34px;
  border: 1px solid rgba(157, 244, 216, 0.12);
  background: #060c18;
}

.comparison-split-panel {
  display: grid;
  grid-template-rows: repeat(5, minmax(88px, auto));
}

.comparison-split-panel.modern {
  background: rgba(29, 158, 117, 0.025);
}

.comparison-split-item {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  padding: 20px 22px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.075);
}

.comparison-split-item:last-child {
  border-bottom: 0;
}

.comparison-split-item span {
  color: rgba(157, 244, 216, 0.58);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
}

.comparison-split-item p {
  margin: 0;
  color: rgba(255, 255, 255, 0.46);
  font-size: 13px;
  line-height: 1.6;
}

.comparison-split-panel.modern .comparison-split-item p {
  color: rgba(255, 255, 255, 0.9);
  font-weight: 500;
}

.comparison-split-center {
  display: grid;
  grid-template-rows: repeat(5, minmax(88px, auto));
  border-left: 1px solid rgba(157, 244, 216, 0.1);
  border-right: 1px solid rgba(157, 244, 216, 0.1);
  background: rgba(255, 255, 255, 0.015);
}

.comparison-split-center span {
  position: relative;
  display: block;
  border-bottom: 1px solid rgba(255, 255, 255, 0.075);
}

.comparison-split-center span:last-child {
  border-bottom: 0;
}

.comparison-split-center span::before {
  content: "";
  position: absolute;
  left: 18px;
  right: 18px;
  top: 50%;
  height: 1px;
  background: rgba(157, 244, 216, 0.52);
}

.comparison-split-center span::after {
  content: "";
  position: absolute;
  right: 17px;
  top: 50%;
  width: 7px;
  height: 7px;
  border-top: 1px solid rgba(157, 244, 216, 0.82);
  border-right: 1px solid rgba(157, 244, 216, 0.82);
  transform: translateY(-50%) rotate(45deg);
}

@media (max-width: 768px) {
  .comparison-split {
    grid-template-columns: 1fr;
  }

  .comparison-split-center {
    display: none;
  }

  .comparison-split-panel {
    grid-template-rows: none;
  }

  .comparison-split-panel.modern {
    border-top: 1px solid rgba(157, 244, 216, 0.12);
  }
}

/* Page 4 paired-card design */
.comparison-pairs {
  display: grid;
  gap: 12px;
  margin-top: 34px;
}

.comparison-pair {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 54px minmax(0, 1fr);
  align-items: stretch;
  min-height: 104px;
  background: #060c18;
  border: 1px solid rgba(157, 244, 216, 0.12);
  transition: transform 220ms ease, border-color 220ms ease, background 220ms ease;
}

.comparison-pair:hover {
  transform: translateY(-3px);
  border-color: rgba(157, 244, 216, 0.28);
  background: #07101f;
}

.comparison-pair p {
  display: flex;
  align-items: center;
  min-height: 100%;
  margin: 0;
  padding: 24px;
  font-size: 13px;
  line-height: 1.62;
}

.comparison-pair p:first-child {
  color: rgba(255, 255, 255, 0.44);
}

.comparison-pair p:last-child {
  color: rgba(255, 255, 255, 0.9);
  font-weight: 500;
  background: rgba(29, 158, 117, 0.025);
}

.comparison-pair span {
  position: relative;
  display: block;
  border-left: 1px solid rgba(157, 244, 216, 0.1);
  border-right: 1px solid rgba(157, 244, 216, 0.1);
  background: rgba(255, 255, 255, 0.012);
}

.comparison-pair span::before {
  content: "";
  position: absolute;
  left: 13px;
  right: 13px;
  top: 50%;
  height: 1px;
  background: rgba(157, 244, 216, 0.56);
}

.comparison-pair span::after {
  content: "";
  position: absolute;
  right: 13px;
  top: 50%;
  width: 7px;
  height: 7px;
  border-top: 1px solid rgba(157, 244, 216, 0.82);
  border-right: 1px solid rgba(157, 244, 216, 0.82);
  transform: translateY(-50%) rotate(45deg);
}

.comparison-pair:nth-child(even) {
  margin-left: 42px;
}

.comparison-pair:nth-child(odd) {
  margin-right: 42px;
}

@media (max-width: 768px) {
  .comparison-pair,
  .comparison-pair:nth-child(even),
  .comparison-pair:nth-child(odd) {
    grid-template-columns: 1fr;
    margin-left: 0;
    margin-right: 0;
  }

  .comparison-pair span {
    height: 34px;
    border-left: 0;
    border-right: 0;
    border-top: 1px solid rgba(157, 244, 216, 0.1);
    border-bottom: 1px solid rgba(157, 244, 216, 0.1);
  }

  .comparison-pair span::before,
  .comparison-pair span::after {
    left: 50%;
    right: auto;
    transform-origin: center;
    transform: translateX(-50%) rotate(90deg);
  }
}

